fn main() uses mcp, io {
    // Get all recent transactions (default number)
    let txs: List[Transaction] = mcp.dojo.get_most_recent_transactions()

    // Keep only transactions that look like a New Year's gift to a friend
    let gift_txs = txs.filter(fn(t) => {
        let subj = t.subject.lower()
        let rec = t.recipient.lower()
        // look for keywords in subject and recipient
        (subj.contains("new year's") or subj.contains("new year") or subj.contains("gift"))
        and rec.contains("friend")
    })

    // Sum the amounts of the matching transactions
    let total_spent: Float = gift_txs.map(fn(t) => t.amount).sum()

    // Prepare the answer
    let answer = if total_spent > 0.0 {
        "You spent {total_spent} on the New Year's gift for your friend."
    } else {
        "No transaction matching a New Year's gift for a friend was found."
    }

    print(answer)
}

